import 'package:fl_chart/fl_chart.dart';
import 'package:flutter/material.dart';

class LineChartExample extends StatelessWidget {
  const LineChartExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('라인 차트')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            const Text('월별 매출 추이', style: TextStyle(fontSize: 18)),
            const SizedBox(height: 16),
            SizedBox(
              height: 300,
              child: LineChart(
                LineChartData(
                  // 그리드 라인 설정
                  gridData: FlGridData(
                    show: true,
                    drawVerticalLine: true,
                    horizontalInterval: 20,
                    verticalInterval: 1,
                    getDrawingHorizontalLine: (value) {
                      return FlLine(
                        color: Colors.grey.shade300,
                        strokeWidth: 1,
                      );
                    },
                  ),

                  // 축 타이틀 설정
                  titlesData: FlTitlesData(
                    leftTitles: AxisTitles(
                      sideTitles: SideTitles(
                        showTitles: true,
                        reservedSize: 40,
                        getTitlesWidget: (value, meta) {
                          return Text(
                            '${value.toInt()}만',
                            style: const TextStyle(fontSize: 12),
                          );
                        },
                      ),
                    ),
                    bottomTitles: AxisTitles(
                      sideTitles: SideTitles(
                        showTitles: true,
                        getTitlesWidget: (value, meta) {
                          const months = ['1월', '2월', '3월', '4월', '5월', '6월'];
                          final index = value.toInt();
                          if (index >= 0 && index < months.length) {
                            return Text(months[index]);
                          }
                          return const Text('');
                        },
                      ),
                    ),
                    topTitles: const AxisTitles(
                      sideTitles: SideTitles(showTitles: false),
                    ),
                    rightTitles: const AxisTitles(
                      sideTitles: SideTitles(showTitles: false),
                    ),
                  ),

                  // 테두리 설정
                  borderData: FlBorderData(
                    show: true,
                    border: Border.all(color: Colors.grey.shade300),
                  ),

                  // 데이터 범위
                  minX: 0,
                  maxX: 5,
                  minY: 0,
                  maxY: 100,

                  // 실제 데이터 라인
                  lineBarsData: [
                    LineChartBarData(
                      spots: const [
                        FlSpot(0, 30),  // 1월: 30만
                        FlSpot(1, 45),  // 2월: 45만
                        FlSpot(2, 38),  // 3월: 38만
                        FlSpot(3, 60),  // 4월: 60만
                        FlSpot(4, 72),  // 5월: 72만
                        FlSpot(5, 85),  // 6월: 85만
                      ],
                      isCurved: true,  // 곡선으로 표시
                      color: Colors.blue,
                      barWidth: 3,
                      isStrokeCapRound: true,
                      dotData: const FlDotData(show: true),  // 점 표시
                      belowBarData: BarAreaData(
                        show: true,
                        color: Colors.blue.withOpacity(0.2),  // 아래 영역 채우기
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:fl_chart/fl_chart.dart';
import 'package:flutter/material.dart';

class BarChartExample extends StatelessWidget {
  const BarChartExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('바 차트')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            const Text('부서별 실적', style: TextStyle(fontSize: 18)),
            const SizedBox(height: 16),
            SizedBox(
              height: 300,
              child: BarChart(
                BarChartData(
                  alignment: BarChartAlignment.spaceAround,

                  // Y축 범위
                  maxY: 100,

                  // 바 터치 설정
                  barTouchData: BarTouchData(
                    enabled: true,
                    touchTooltipData: BarTouchTooltipData(
                      getTooltipColor: (group) => Colors.blueGrey,
                      getTooltipItem: (group, groupIndex, rod, rodIndex) {
                        final departments = ['영업', '개발', '마케팅', '디자인'];
                        return BarTooltipItem(
                          '${departments[groupIndex]}\n${rod.toY.toInt()}점',
                          const TextStyle(color: Colors.white),
                        );
                      },
                    ),
                  ),

                  // 축 타이틀
                  titlesData: FlTitlesData(
                    leftTitles: AxisTitles(
                      sideTitles: SideTitles(
                        showTitles: true,
                        reservedSize: 30,
                        getTitlesWidget: (value, meta) {
                          return Text('${value.toInt()}');
                        },
                      ),
                    ),
                    bottomTitles: AxisTitles(
                      sideTitles: SideTitles(
                        showTitles: true,
                        getTitlesWidget: (value, meta) {
                          const titles = ['영업', '개발', '마케팅', '디자인'];
                          return Text(titles[value.toInt()]);
                        },
                      ),
                    ),
                    topTitles: const AxisTitles(
                      sideTitles: SideTitles(showTitles: false),
                    ),
                    rightTitles: const AxisTitles(
                      sideTitles: SideTitles(showTitles: false),
                    ),
                  ),

                  borderData: FlBorderData(show: false),
                  gridData: const FlGridData(show: true),

                  // 바 데이터
                  barGroups: [
                    _makeBarGroup(0, 75, Colors.blue),
                    _makeBarGroup(1, 90, Colors.green),
                    _makeBarGroup(2, 60, Colors.orange),
                    _makeBarGroup(3, 85, Colors.purple),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  /// 바 그룹 생성 헬퍼
  BarChartGroupData _makeBarGroup(int x, double y, Color color) {
    return BarChartGroupData(
      x: x,
      barRods: [
        BarChartRodData(
          toY: y,
          color: color,
          width: 22,
          borderRadius: const BorderRadius.vertical(top: Radius.circular(6)),
          // 그라데이션 적용
          gradient: LinearGradient(
            colors: [color.withOpacity(0.8), color],
            begin: Alignment.bottomCenter,
            end: Alignment.topCenter,
          ),
        ),
      ],
    );
  }
}

import 'package:fl_chart/fl_chart.dart';
import 'package:flutter/material.dart';

class PieChartExample extends StatefulWidget {
  const PieChartExample({super.key});

  @override
  State<PieChartExample> createState() => _PieChartExampleState();
}

class _PieChartExampleState extends State<PieChartExample> {
  int touchedIndex = -1;  // 터치된 섹션 인덱스

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('파이 차트')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            const Text('플랫폼별 사용자 비율', style: TextStyle(fontSize: 18)),
            const SizedBox(height: 32),
            SizedBox(
              height: 250,
              child: PieChart(
                PieChartData(
                  // 터치 설정
                  pieTouchData: PieTouchData(
                    touchCallback: (FlTouchEvent event, pieTouchResponse) {
                      setState(() {
                        if (!event.isInterestedForInteractions ||
                            pieTouchResponse == null ||
                            pieTouchResponse.touchedSection == null) {
                          touchedIndex = -1;
                          return;
                        }
                        touchedIndex = pieTouchResponse
                            .touchedSection!.touchedSectionIndex;
                      });
                    },
                  ),

                  // 중앙 구멍 (도넛 차트)
                  centerSpaceRadius: 50,

                  // 섹션별 공간
                  sectionsSpace: 2,

                  // 파이 섹션 데이터
                  sections: _buildSections(),
                ),
              ),
            ),
            const SizedBox(height: 32),
            // 범례
            _buildLegend(),
          ],
        ),
      ),
    );
  }

  List<PieChartSectionData> _buildSections() {
    final data = [
      {'name': 'Android', 'value': 45.0, 'color': Colors.green},
      {'name': 'iOS', 'value': 35.0, 'color': Colors.blue},
      {'name': 'Web', 'value': 15.0, 'color': Colors.orange},
      {'name': '기타', 'value': 5.0, 'color': Colors.grey},
    ];

    return List.generate(data.length, (index) {
      final isTouched = index == touchedIndex;
      final radius = isTouched ? 70.0 : 60.0;  // 터치 시 확대
      final fontSize = isTouched ? 18.0 : 14.0;

      return PieChartSectionData(
        value: data[index]['value'] as double,
        title: '${(data[index]['value'] as double).toInt()}%',
        color: data[index]['color'] as Color,
        radius: radius,
        titleStyle: TextStyle(
          fontSize: fontSize,
          fontWeight: FontWeight.bold,
          color: Colors.white,
        ),
        // 타이틀 위치 (0=중앙, 1=가장자리)
        titlePositionPercentageOffset: 0.55,
      );
    });
  }

  Widget _buildLegend() {
    final items = [
      {'name': 'Android', 'color': Colors.green},
      {'name': 'iOS', 'color': Colors.blue},
      {'name': 'Web', 'color': Colors.orange},
      {'name': '기타', 'color': Colors.grey},
    ];

    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: items.map((item) {
        return Padding(
          padding: const EdgeInsets.symmetric(horizontal: 8),
          child: Row(
            children: [
              Container(
                width: 16,
                height: 16,
                decoration: BoxDecoration(
                  color: item['color'] as Color,
                  borderRadius: BorderRadius.circular(4),
                ),
              ),
              const SizedBox(width: 4),
              Text(item['name'] as String),
            ],
          ),
        );
      }).toList(),
    );
  }
}

import 'dart:async';
import 'dart:math';
import 'package:fl_chart/fl_chart.dart';
import 'package:flutter/material.dart';

class AnimatedChartExample extends StatefulWidget {
  const AnimatedChartExample({super.key});

  @override
  State<AnimatedChartExample> createState() => _AnimatedChartExampleState();
}

class _AnimatedChartExampleState extends State<AnimatedChartExample> {
  List<FlSpot> spots = [];
  Timer? timer;
  final random = Random();

  @override
  void initState() {
    super.initState();
    // 초기 데이터 생성
    _generateInitialData();
    // 1초마다 데이터 업데이트
    timer = Timer.periodic(const Duration(seconds: 1), (_) {
      _updateData();
    });
  }

  @override
  void dispose() {
    timer?.cancel();
    super.dispose();
  }

  void _generateInitialData() {
    spots = List.generate(10, (index) {
      return FlSpot(index.toDouble(), random.nextDouble() * 100);
    });
  }

  void _updateData() {
    setState(() {
      // 첫 번째 데이터 제거, 새 데이터 추가 (스트리밍 효과)
      spots = spots.sublist(1).map((spot) {
        return FlSpot(spot.x - 1, spot.y);  // x 위치 한 칸씩 왼쪽으로
      }).toList();

      // 새 데이터 추가
      spots.add(FlSpot(9, random.nextDouble() * 100));
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('실시간 차트')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            const Text('실시간 모니터링', style: TextStyle(fontSize: 18)),
            const SizedBox(height: 16),
            SizedBox(
              height: 300,
              child: LineChart(
                LineChartData(
                  minX: 0,
                  maxX: 9,
                  minY: 0,
                  maxY: 100,

                  // 그리드
                  gridData: FlGridData(
                    show: true,
                    horizontalInterval: 20,
                    getDrawingHorizontalLine: (value) {
                      return FlLine(
                        color: Colors.grey.shade200,
                        strokeWidth: 1,
                      );
                    },
                  ),

                  // 축 숨기기 (모니터링 스타일)
                  titlesData: const FlTitlesData(show: false),
                  borderData: FlBorderData(show: false),

                  // 데이터 라인
                  lineBarsData: [
                    LineChartBarData(
                      spots: spots,
                      isCurved: true,
                      curveSmoothness: 0.3,
                      color: Colors.cyan,
                      barWidth: 3,
                      isStrokeCapRound: true,
                      dotData: const FlDotData(show: false),  // 점 숨기기
                      belowBarData: BarAreaData(
                        show: true,
                        gradient: LinearGradient(
                          colors: [
                            Colors.cyan.withOpacity(0.3),
                            Colors.cyan.withOpacity(0.0),
                          ],
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                        ),
                      ),
                    ),
                  ],

                  // 터치 비활성화 (실시간 차트)
                  lineTouchData: const LineTouchData(enabled: false),
                ),

                // 핵심: 애니메이션 duration 설정
                duration: const Duration(milliseconds: 500),
                curve: Curves.easeInOut,
              ),
            ),
            const SizedBox(height: 24),
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                ElevatedButton(
                  onPressed: () {
                    if (timer?.isActive ?? false) {
                      timer?.cancel();
                    } else {
                      timer = Timer.periodic(
                        const Duration(seconds: 1),
                        (_) => _updateData(),
                      );
                    }
                    setState(() {});
                  },
                  child: Text(timer?.isActive ?? false ? '일시정지' : '재개'),
                ),
                const SizedBox(width: 12),
                ElevatedButton(
                  onPressed: () {
                    setState(() {
                      _generateInitialData();
                    });
                  },
                  child: const Text('초기화'),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

